Lemma grow_munmap : forall A A' h (a n : word),
  VMok A h -> In (a, n) (vm_maps h) -> a_areas A' = a_areas A -> spare A <= spare A' ->
  sgrow (-1) 0 0 A A' h (vm_munmap a n h).
